#!/usr/bin/env python3
import os, json, io, urllib.request, urllib.parse, time, secrets, base64
from http.server import ThreadingHTTPServer, SimpleHTTPRequestHandler
from pathlib import Path
from datetime import datetime, timezone, timedelta

from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.utils import ImageReader

ROOT = Path(__file__).resolve().parent

# Embedded pieces taken from the approved SARMAT DOORS commercial-proposal sample:
# header: exact approved navy header/logo/company block
# signature: approved signature/stamp area
HEADER_B64 = ""
SIGN_B64 = ""

def load_env_file():
    env = ROOT / ".env"
    if not env.exists():
        return
    for raw in env.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        k, v = k.strip(), v.strip().strip('"').strip("'")
        if k and k not in os.environ:
            os.environ[k] = v
load_env_file()

FONT = "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"
FONTB = "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"
if Path(FONT).exists():
    pdfmetrics.registerFont(TTFont("DV", FONT))
    pdfmetrics.registerFont(TTFont("DVB", FONTB))
    BASEFONT, BOLD = "DV", "DVB"
else:
    BASEFONT, BOLD = "Helvetica", "Helvetica-Bold"

TOKEN = os.environ.get("TELEGRAM_BOT_TOKEN", "").strip()
CHAT_ID = os.environ.get("TELEGRAM_CHAT_ID", "").strip()

def money(n):
    return f"{round(float(n)):,}".replace(",", " ") + " сум"

def esc(s):
    return str(s if s is not None else "").replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")

def img_from_b64(data):
    return ImageReader(io.BytesIO(base64.b64decode(data)))

def tg_request(method, fields=None, files=None):
    if not TOKEN or not CHAT_ID:
        raise RuntimeError("Telegram не настроен: задайте TELEGRAM_BOT_TOKEN и TELEGRAM_CHAT_ID")
    fields = fields or {}
    if not files:
        data = urllib.parse.urlencode(fields).encode()
        req = urllib.request.Request(
            f"https://api.telegram.org/bot{TOKEN}/{method}",
            data=data, method="POST"
        )
    else:
        boundary = "----SarmatBoundary" + secrets.token_hex(8)
        chunks = []
        for k, v in fields.items():
            chunks += [
                f"--{boundary}\r\n".encode(),
                f'Content-Disposition: form-data; name="{k}"\r\n\r\n'.encode(),
                str(v).encode(), b"\r\n"
            ]
        for name, (filename, content, ctype) in files.items():
            chunks += [
                f"--{boundary}\r\n".encode(),
                f'Content-Disposition: form-data; name="{name}"; filename="{filename}"\r\n'.encode(),
                f"Content-Type: {ctype}\r\n\r\n".encode(),
                content, b"\r\n"
            ]
        chunks.append(f"--{boundary}--\r\n".encode())
        data = b"".join(chunks)
        req = urllib.request.Request(
            f"https://api.telegram.org/bot{TOKEN}/{method}",
            data=data, method="POST",
            headers={"Content-Type": f"multipart/form-data; boundary={boundary}"}
        )
    with urllib.request.urlopen(req, timeout=25) as r:
        result = json.loads(r.read().decode())
    if not result.get("ok"):
        raise RuntimeError(result.get("description", "Telegram API error"))
    return result

def tg_send(text):
    return tg_request("sendMessage", {"chat_id": CHAT_ID, "text": text})

def tg_send_pdf(pdf_bytes, filename, caption):
    return tg_request(
        "sendDocument",
        {"chat_id": CHAT_ID, "caption": caption},
        {"document": (filename, pdf_bytes, "application/pdf")}
    )

def build_row(x, i, styles):
    typ = x.get("doorType", "Противопожарная")
    cls = "Не применяется" if typ == "Техническая" else x.get("cls", "—")
    w = float(x.get("w", 0))
    h = float(x.get("h", 0))
    qty = int(x.get("qty", 1) or 1)
    unit = float(x.get("total", 0) or 0)
    total = unit * qty

    # Keep the approved quotation naming style compact.
    if x.get("name"):
        name = str(x["name"])
    elif typ == "Техническая":
        name = f"Дверь техническая {int(w)}×{int(h)}"
    else:
        name = f"Дверь металлическая противопожарная {cls} {int(w)}×{int(h)}"

    # The approved sample keeps the Notes column short. Detailed configurator
    # parameters remain in the Telegram order message; the quotation uses the
    # concise project-style note.
    note = x.get("comment")
    if not note:
        if typ != "Техническая":
            note = "С уплотнением в притворах"
            if x.get("closer"):
                note += ", с доводчиком"
            if x.get("threshold"):
                note += ", высота порога не более 14 мм"
        else:
            note = "Согласно комплектации заказа"
    remark = esc(note)

    return [
        Paragraph(str(i), styles["Tiny"]),
        Paragraph("<b>" + esc(name) + "</b>", styles["Tiny"]),
        f"{w/1000:.2f}×{h/1000:.2f}",
        str(qty),
        Paragraph(remark, styles["Tiny"]),
        Paragraph(money(unit), styles["Tiny"]),
        Paragraph(money(total), styles["Tiny"]),
    ], total, qty

def make_pdf(payload, signed=True):
    c = payload.get("customer") or {}
    oid = payload.get("orderId", "SARMAT-ORDER")
    order = payload.get("order") or []

    # In the approved format, x.total is the complete per-door price.
    # Installation/delivery/foam is a separate 600,000 sum per door when selected.
    door_subtotal = 0.0
    install_total = 0.0
    total_qty = 0
    for x in order:
        qty = int(x.get("qty", 1) or 1)
        unit = float(x.get("total", 0) or 0)
        inst = float(x.get("inst", 0) or 0)
        # Frontend stores total including installation in some versions.
        # Remove selected installation from the door subtotal, then add it back
        # as a separate commercial condition.
        pos_total = unit * qty
        pos_inst = inst * qty
        door_subtotal += pos_total - pos_inst
        install_total += pos_inst
        total_qty += qty
    overall_total = door_subtotal + install_total

    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(
        name="RU", fontName=BASEFONT, fontSize=7.2, leading=9.0,
        textColor=colors.HexColor("#111111")
    ))
    styles.add(ParagraphStyle(
        name="Tiny", parent=styles["RU"], fontSize=6.15, leading=7.35
    ))
    styles.add(ParagraphStyle(
        name="TinyB", parent=styles["Tiny"], fontName=BOLD
    ))
    styles.add(ParagraphStyle(
        name="H1", parent=styles["RU"], fontName=BOLD, fontSize=17,
        leading=20, textColor=colors.HexColor("#0b2438"), alignment=1
    ))
    styles.add(ParagraphStyle(
        name="Gold", parent=styles["RU"], fontName=BOLD, fontSize=9.6,
        leading=12, textColor=colors.HexColor("#b99132"), alignment=1
    ))
    styles.add(ParagraphStyle(
        name="Section", parent=styles["RU"], fontName=BOLD, fontSize=9.2,
        leading=11, textColor=colors.HexColor("#b99132"),
        spaceBefore=6, spaceAfter=4
    ))
    styles.add(ParagraphStyle(
        name="TermsTitle", parent=styles["H1"], fontSize=15, leading=18,
        spaceBefore=5, spaceAfter=8
    ))

    story = []
    story.append(Spacer(1, 3))
    story.append(Paragraph(f"<b>№ {esc(oid)}</b><br/>Дата: {datetime.now(timezone(timedelta(hours=5))).strftime('%d.%m.%Y')} г.", styles["RU"]))
    if c.get("company") or c.get("person") or c.get("phone"):
        # Kept compact; the approved sample itself does not make this a large block.
        story.append(Spacer(1, 3))
        customer_line = " · ".join([str(v) for v in [c.get("company"), c.get("person"), c.get("phone")] if v])
        story.append(Paragraph(f"<b>Заказчик:</b> {esc(customer_line)}", styles["RU"]))

    story += [
        Spacer(1, 7),
        Paragraph("КОММЕРЧЕСКОЕ ПРЕДЛОЖЕНИЕ", styles["H1"]),
        Paragraph("Поставка и монтаж металлических и противопожарных дверей.", styles["Gold"]),
        Spacer(1, 7),
        Paragraph(
            "<b>Уважаемые коллеги!</b><br/>"
            "ООО «SARMAT DOORS» предлагает изготовление, поставку и монтаж металлических и противопожарных дверей по представленному перечню. "
            "Все позиции изготавливаются индивидуально по размерам и техническим требованиям.",
            styles["RU"]
        ),
        Paragraph("ОСНОВНЫЕ ТЕХНИЧЕСКИЕ ХАРАКТЕРИСТИКИ", styles["Section"]),
    ]

    bullets = [
        "Полотно двери — холоднокатаная сталь толщиной 1,2 мм.",
        "Коробка — холоднокатаная сталь толщиной 1,5 мм.",
        "Заполнение противопожарных дверей — каменная вата высокой плотности (ориентировочно 80 кг/м³), с учетом требований конструкции и испытаний.",
        "Противопожарные двери комплектуются необходимыми уплотнениями и доводчиками согласно соответствующей позиции.",
        "Для позиций с выпадающим порогом предусматривается соответствующая фурнитура.",
        "Противопожарные двери SARMAT DOORS имеют сертификаты пожарной безопасности и протоколы испытаний на соответствующий предел огнестойкости.",
    ]
    for b in bullets:
        story.append(Paragraph("• " + esc(b), styles["RU"]))

    story.append(Paragraph("СТОИМОСТЬ", styles["Section"]))

    header = [
        Paragraph("<b>№</b>", styles["TinyB"]),
        Paragraph("<b>Наименование</b>", styles["TinyB"]),
        Paragraph("<b>Размер, м</b>", styles["TinyB"]),
        Paragraph("<b>Кол-во</b>", styles["TinyB"]),
        Paragraph("<b>Примечание</b>", styles["TinyB"]),
        Paragraph("<b>Цена за 1 шт.,<br/>сум</b>", styles["TinyB"]),
        Paragraph("<b>Сумма, сум</b>", styles["TinyB"]),
    ]

    rows = []
    row_totals = []
    for i, x in enumerate(order, 1):
        row, _, qty = build_row(x, i, styles)
        rows.append(row)
        row_totals.append(qty)

    # Keep the approved visual proportions. The last table page must leave room
    # for "УСЛОВИЯ ПОСТАВКИ И ОПЛАТЫ", so split the table into manageable chunks.
    # 50-position quotations naturally become ~4 pages in this layout.
    # The approved sample uses a compact first page and reserves the last page
    # for the final rows + the commercial-terms block.
    target_sizes = [9, 15, 21, 5]
    chunks = []
    pos = 0
    for size in target_sizes:
        if pos >= len(rows):
            break
        chunks.append(rows[pos:pos+size])
        pos += size
    if pos < len(rows):
        # More than 50 positions: continue in safe 17-row chunks, while keeping
        # the final five rows for the terms block.
        while len(rows) - pos > 5:
            take = min(17, len(rows) - pos - 5)
            chunks.append(rows[pos:pos+take])
            pos += take
        if pos < len(rows):
            chunks.append(rows[pos:])
    if not chunks:
        chunks = [[]]

    for ci, chunk in enumerate(chunks):
        data = [header] + chunk
        if ci == len(chunks) - 1:
            data.append([
                "", "", "", "",
                Paragraph(f"<b>Итого дверей ({total_qty} шт.):</b>", styles["TinyB"]),
                "",
                Paragraph(f"<b>{money(door_subtotal)}</b>", styles["TinyB"])
            ])

        tbl = Table(
            data,
            colWidths=[22, 105, 48, 34, 190, 65, 67],
            repeatRows=1,
            splitByRow=1
        )
        tbl.setStyle(TableStyle([
            ("GRID", (0,0), (-1,-1), 0.35, colors.HexColor("#c5ccd1")),
            ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#eef0f1")),
            ("VALIGN", (0,0), (-1,-1), "TOP"),
            ("LEFTPADDING", (0,0), (-1,-1), 3),
            ("RIGHTPADDING", (0,0), (-1,-1), 3),
            ("TOPPADDING", (0,0), (-1,-1), 2.5),
            ("BOTTOMPADDING", (0,0), (-1,-1), 2.5),
        ]))
        if ci == len(chunks) - 1:
            tbl.setStyle(TableStyle([("SPAN", (0,-1), (4,-1))]))
        story.append(tbl)
        if ci != len(chunks) - 1:
            story.append(PageBreak())
            # Subsequent pages only need the table; the page callback supplies the header.

    story += [
        Spacer(1, 9),
        Paragraph("УСЛОВИЯ ПОСТАВКИ И ОПЛАТЫ", styles["TermsTitle"])
    ]

    terms = [
        ["Монтаж, доставка и пена", f"600 000 сум за 1 дверь — отдельная позиция. Всего за {total_qty} дверей: {money(install_total)}."],
        ["Стоимость дверей", money(door_subtotal)],
        ["Общая стоимость с монтажом, доставкой и пеной", money(overall_total)],
        ["Оплата", "70% — предоплата; 30% — до поставки товара."],
        ["Цена", "Указанные цены рассчитаны с учетом НДС."],
        ["Сроки поставки и изготовления", "Согласовывается при подписании заказа и утверждении рабочих размеров."],
        ["Гарантия 1 год", "Предоставляется на изготовленные изделия и выполненные монтажные работы согласно договору."],
    ]
    terms_tbl = Table(
        [[Paragraph(esc(a), styles["TinyB"]), Paragraph(esc(b), styles["RU"])] for a,b in terms],
        colWidths=[160, 371]
    )
    terms_tbl.setStyle(TableStyle([
        ("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#c9cfd3")),
        ("VALIGN",(0,0),(-1,-1),"TOP"),
        ("BACKGROUND",(0,0),(0,-1),colors.HexColor("#f3f3f3")),
        ("LEFTPADDING",(0,0),(-1,-1),4),
        ("RIGHTPADDING",(0,0),(-1,-1),4),
        ("TOPPADDING",(0,0),(-1,-1),4),
        ("BOTTOMPADDING",(0,0),(-1,-1),4),
    ]))
    story.append(terms_tbl)

    if signed:
        story.append(Spacer(1, 8))
        # The approved signature/stamp is embedded so the PDF does not depend on
        # external PNG files being present on Render.
        sign_img = Image(io.BytesIO(base64.b64decode(SIGN_B64)), width=250, height=112)
        sign_img.hAlign = "LEFT"
        story.append(sign_img)

    story.append(Spacer(1, 4))

    def header_footer(canv, doc):
        canv.saveState()
        W, H = A4
        # Exact approved header/logo block.
        try:
            canv.drawImage(img_from_b64(HEADER_B64), 0, H-78, width=W, height=78,
                           preserveAspectRatio=False, mask="auto")
        except Exception:
            canv.setFillColor(colors.HexColor("#061a2b"))
            canv.rect(0, H-78, W, 78, fill=1, stroke=0)
            canv.setFillColor(colors.white)
            canv.setFont(BOLD, 15)
            canv.drawString(42, H-44, "SARMAT DOORS")

        canv.setStrokeColor(colors.HexColor("#d7b25a"))
        canv.line(36, H-89, W-36, H-89)

        canv.setFillColor(colors.HexColor("#68737b"))
        canv.setFont(BASEFONT, 6.5)
        canv.drawCentredString(
            W/2, 18,
            'ООО "SARMAT DOORS"  •  ИНН 313 122 742  •  Р/С 2020 8000 9074 8926 7001  •  МФО 01071'
        )
        canv.restoreState()

    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=A4,
        rightMargin=30, leftMargin=30,
        topMargin=100, bottomMargin=34,
        title=f"SARMAT DOORS — {oid}",
        author="ООО SARMAT DOORS"
    )
    doc.build(story, onFirstPage=header_footer, onLaterPages=header_footer)
    raw = buf.getvalue()

    if not raw.startswith(b"%PDF-"):
        raise RuntimeError("PDF generation returned invalid data")
    return raw

def make_final_pdf(payload):
    return make_pdf(payload, signed=True)

RATE = {}
RATE_WINDOW = 60
RATE_MAX = 20
MAX_BODY = 1024 * 1024

class Handler(SimpleHTTPRequestHandler):
    def _cors(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")

    def _json(self, code, obj):
        b = json.dumps(obj, ensure_ascii=False).encode()
        self.send_response(code)
        self._cors()
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def _pdf(self, b, filename):
        if not b.startswith(b"%PDF-"):
            raise RuntimeError("Сервер сформировал некорректный PDF")
        self.send_response(200)
        self._cors()
        self.send_header("Content-Type", "application/pdf")
        self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
        self.send_header("Pragma", "no-cache")
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_OPTIONS(self):
        self.send_response(204)
        self._cors()
        self.end_headers()

    def do_GET(self):
        if self.path == "/api/health":
            return self._json(200, {
                "ok": True,
                "telegramConfigured": bool(TOKEN and CHAT_ID),
                "pdf": True,
                "finalPdf": True,
                "pdfEngine": "reportlab-approved-template-v2"
            })
        return super().do_GET()

    def do_POST(self):
        ip = self.client_address[0]
        now = time.time()
        hist = [t for t in RATE.get(ip, []) if now-t < RATE_WINDOW]
        if len(hist) >= RATE_MAX:
            return self._json(429, {"ok": False, "error": "Слишком много запросов. Попробуйте позже."})
        hist.append(now)
        RATE[ip] = hist

        try:
            n = int(self.headers.get("Content-Length", "0"))
        except Exception:
            n = 0
        if n < 1 or n > MAX_BODY:
            return self._json(413, {"ok": False, "error": "Некорректный размер запроса"})

        body = self.rfile.read(n)
        try:
            p = json.loads(body.decode())
        except Exception:
            return self._json(400, {"ok": False, "error": "Некорректный JSON"})

        if self.path in ("/api/pdf", "/api/final-pdf"):
            try:
                b = make_final_pdf(p)
                name = f'{p.get("orderId","SARMAT_DOORS")}_SARMAT_DOORS.pdf'
                return self._pdf(b, name)
            except Exception as e:
                return self._json(500, {"ok": False, "error": f"PDF: {e}"})

        if self.path == "/api/order":
            try:
                order = p.get("order") or []
                total = sum(float(x.get("total",0) or 0) * int(x.get("qty",1) or 1) for x in order)
                qty = sum(int(x.get("qty",1) or 1) for x in order)
                lines = [
                    "🟢 SARMAT DOORS — новая заявка",
                    f'№ {p.get("orderId","—")}',
                    f'Клиент: {(p.get("customer") or {}).get("company","")} / {(p.get("customer") or {}).get("person","")}',
                    f'Телефон: {(p.get("customer") or {}).get("phone","")}',
                    f"Дверей: {qty}",
                    f"Позиций: {len(order)}",
                    f"Итого: {money(total)}",
                    ""
                ]
                for i, x in enumerate(order, 1):
                    lines += [
                        f'Позиция {i}: {x.get("doorType","Противопожарная")} {x.get("cls","—")} {x.get("w","—")}×{x.get("h","—")} · {x.get("qty",1)} шт.',
                        f'Открывание: {x.get("opening","—")} · Сталь: {x.get("leafMm","—")}/{x.get("frameMm","—")} мм · RAL: {x.get("ralText","—")}',
                        f'Фурнитура: {x.get("hwText","—")}',
                        f'Доводчик: {"Да — "+money(400000) if x.get("closer") else "Нет"}',
                        f'Примечание: {x.get("comment") or "—"}',
                        ""
                    ]
                pdf = make_final_pdf(p)
                tg_send("\n".join(lines))
                tg_send_pdf(
                    pdf,
                    f'{p.get("orderId","SARMAT_DOORS")}_SARMAT_DOORS.pdf',
                    f'Коммерческое предложение {p.get("orderId","—")} · {qty} дверей · {money(total)}'
                )
                return self._json(200, {"ok": True, "orderId": p.get("orderId"), "pdfSent": True, "finalPdf": True})
            except Exception as e:
                return self._json(502, {"ok": False, "error": f"Не удалось отправить заявку в Telegram: {e}"})

        if self.path == "/api/telegram-test":
            try:
                tg_send("🟢 ТЕСТ TELEGRAM — SARMAT DOORS\nСвязь сайта с рабочей группой проверена.")
                return self._json(200, {"ok": True})
            except Exception as e:
                return self._json(502, {"ok": False, "error": str(e)})

        return self._json(404, {"ok": False, "error": "Not found"})

    def log_message(self, format, *args):
        pass

if __name__ == "__main__":
    os.chdir(ROOT)
    port = int(os.environ.get("PORT", "8080"))
    print(f"SARMAT DOORS B2B PDF v2: http://0.0.0.0:{port}")
    ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()
